// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, address actor) public {
        // Admissible actor: must be a distinct non-zero address. Keep domain wide.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        // Fund the actor to satisfy the 1 ether lock-in requirement.
        vm.deal(actor, 1 ether);

        // Actor locks in a guess at the current block; records block = block.number + 1.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance to exactly the block stored as the guess block: B = block.number + 1.
        // At block number B, the reference's `block.number > B` is false and settle MUST revert,
        // whereas the bug's `block.number >= B` is true and settle MUST NOT revert at the guard.
        vm.roll(block.number + 1);

        vm.prank(actor);
        bool settleSucceeded;
        try c.settle() {
            settleSucceeded = true;
        } catch {
            settleSucceeded = false;
        }

        // General rule: at the exact stored guess block, settle must revert for every admissible input.
        assertTrue(!settleSucceeded);
    }
}
